/* Local, transparent planning checks. No semantic verdict or external requests. */
(function(root){
'use strict';
const text=(d,k)=>String(d[k]||'').trim();
function analyze(d,tasks=[]){
 const findings=[];
 const add=(id,category,title,observation,action,keys,pattern)=>{
  const evidence=keys.filter(k=>text(d,k)).map(k=>({field:k,text:text(d,k).slice(0,700)}));
  findings.push({id,category,title,observation,action,evidence,field:keys[0],kind:pattern?'pattern':'missing'});
 };
 const required=[['question','Fragestellung','Forschungsfrage fehlt','Formuliere eine untersuchbare Frage.'],['scope','Fragestellung','Themeneingrenzung fehlt','Lege Gegenstand, Zeitraum, Raum oder Personengruppe und zentrale Begriffe fest.'],['goal','Fragestellung','Erkenntnisziel fehlt','Beschreibe, welche Erkenntnis die Antwort liefern soll.'],['method','Methode und Daten','Hauptmethode fehlt','Wähle eine Methode, die das Erkenntnisziel bearbeiten kann.'],['material','Methode und Daten','Untersuchungsmaterial fehlt','Nenne Daten, Fälle oder Texte und begründe ihre Auswahl.'],['analysis','Methode und Daten','Auswertung fehlt','Lege fest, wie Daten oder Texte ausgewertet werden.'],['methodFit','Methode und Daten','Passung von Frage und Methode offen','Erkläre, welche Antwort deine Methode ermöglicht und welche nicht.'],['alignment','Aufbau und Zusammenhang','Zuordnung der Teilfragen fehlt','Ordne jeder Teilfrage Material, Methode und Auswertung zu.'],['literature','Belege und Quellen','Literaturgrundlage fehlt','Trage tatsächlich gefundene Quellen mit vollständigen bibliografischen Angaben ein.'],['sourcecheck','Belege und Quellen','Funktion der Quellen offen','Ordne wichtige Quellen einer Teilfrage zu und prüfe Autorität, Aktualität und Belege.'],['claim','Begründung und Schlussregel','Zentrale Annahme nicht expliziert','Nenne eine vorläufige, überprüfbare Annahme oder begründe, warum du explorativ ohne Hypothese arbeitest.'],['evidencePlan','Begründung und Schlussregel','Geplante Belege offen','Welche Beobachtung oder Textstelle würde die Annahme stützen, welche ihr widersprechen?'],['warrant','Begründung und Schlussregel','Schlussregel noch offen','Erkläre, warum die geplanten Belege die vorgesehene Schlussfolgerung tragen könnten.'],['alternatives','Gegenargumente und Differenzierung','Alternative Erklärung fehlt','Nenne eine plausible Gegenposition oder Alternativerklärung und wie du sie prüfen könntest.'],['limits','Gegenargumente und Differenzierung','Aussagegrenzen fehlen','Grenze ein, für welche Fälle deine Ergebnisse gelten können.'],['feasibility','Machbarkeit','Datenzugang ungeklärt','Beschreibe Zugang, Zeit und Ressourcen.'],['risks','Machbarkeit','Risiken und Plan B fehlen','Nenne einen realistischen Ausfall und eine Alternative.'],['outline','Aufbau und Zusammenhang','Gliederung fehlt','Plane Grundlagen, Methode, Ergebnisse, Diskussion und Fazit.']];
 required.forEach(([k,c,t,a])=>{if(!text(d,k))add('missing-'+k,c,t,'Dazu ist noch keine Angabe erfasst.',a,[k])});
 const q=text(d,'question');
 if(q&&!/\?\s*$/.test(q))add('question-form','Fragestellung','Frageform prüfen','Die Forschungsfrage endet nicht mit einem Fragezeichen.','Formuliere die zentrale Frage als einzelne, klar verständliche Frage.',['question'],true);
 if(q&&/^(ist|sind|hat|haben|kann|können|soll|sollen|wird|werden)\b/i.test(q))add('closed','Fragestellung','Möglicherweise enge Ja-/Nein-Frage','Der Fragebeginn lässt eine Ja-/Nein-Antwort zu. Auch eine solche Frage kann geeignet sein, wenn die Kriterien klar sind.','Prüfe, ob eine offene Frage oder explizite Entscheidungskriterien mehr Erkenntnis ermöglichen.',['question'],true);
 if(/beweisen|bestätigen|bestätigt|nachweisen,? dass/i.test([q,text(d,'goal'),text(d,'claim')].join(' ')))add('confirmation','Gegenargumente und Differenzierung','Ergebnisoffenheit prüfen','Eine Formulierung deutet auf ein vorweggenommenes Ergebnis hin.','Ersetze ein reines Bestätigungsziel durch eine Prüfung. Welche Befunde würden die Annahme widerlegen?',['goal','question','claim'],true);
 const causal=/\b(verursach\w*|bewirk\w*|führt zu|führen zu|einfluss|wirkung\w*|effekt\w*)\b/i.test(q+' '+text(d,'goal'));
 const observational=/Interviews|Umfrage|Beobachtung/i.test(text(d,'method'));
 if(causal&&observational)add('causal','Methode und Daten','Kausalität mit Beobachtungsdaten prüfen','Die Frage oder das Ziel nennt Wirkung/Einfluss; die gewählte Methode ist beobachtend oder erhebt Selbstauskünfte. Das ist ein Prüfhinweis, kein Beweis für einen Fehlschluss.','Unterscheide Ursache, Zusammenhang und subjektive Zuschreibung. Plane den Umgang mit Störfaktoren oder grenze die Frage ein.',['question','method','goal'],true);
 if(/Interviews|Umfrage/i.test(text(d,'method'))&&!text(d,'procedure'))add('instrument','Methode und Daten','Erhebungsinstrument fehlt','Eine Befragungsmethode ist gewählt, aber ihre Durchführung ist noch offen.','Plane Leitfaden oder Fragebogen, Auswahl, Umfang, Einwilligung und einen Probelauf.',['procedure','method'],true);
 const substantive=['question','goal','claim','warrant'];
 if(substantive.some(k=>/\b(alle|jeder|jede|immer|niemals|zwangsläufig|ausnahmslos)\b/i.test(text(d,k))))add('generalization','Gegenargumente und Differenzierung','Reichweite der Aussagen prüfen','Im Erkenntnisziel oder in der Begründung steht eine absolute Formulierung.','Prüfe, ob Auswahl und Daten eine solche Verallgemeinerung erlauben; benenne Ausnahmen und Geltungsbereich.',substantive.filter(k=>/\b(alle|jeder|jede|immer|niemals|zwangsläufig|ausnahmslos)\b/i.test(text(d,k))),true);
 if(/keine?\s+(Interviews|Befragung\w*|Umfrage\w*)/i.test(text(d,'scope'))&&/Interviews|Umfrage/i.test(text(d,'method')))add('scope-method','Methode und Daten','Möglicher Widerspruch bei der Methodenwahl','Die Eingrenzung scheint Befragungen auszuschliessen, während die Hauptmethode eine Befragung nennt.','Kläre, was genau ausgeschlossen wird, und gleiche Eingrenzung und Methode ab.',['scope','method'],true);
 const lit=text(d,'literature');
 if(lit&&(/noch keine|nachtragen|ergänzen|platzhalter|\btodo\b/i.test(lit)||!/(?:18|19|20)\d{2}|\bo\.?\s?J\.?\b/i.test(lit)))add('bibliography','Belege und Quellen','Bibliografische Angaben prüfen','Die Literaturliste enthält Platzhalter oder keine erkennbare Jahresangabe (bzw. o. J.).','Prüfe jede Quelle am Original. Ergänze Autor/in, Jahr, Titel, Publikationsort und DOI/URL soweit zutreffend. Das Tool verifiziert keine Quellen.',['literature'],true);
 if(text(d,'hypothesis')&&!text(d,'evidencePlan'))add('testability','Begründung und Schlussregel','Hypothese noch nicht operationalisiert','Es gibt eine Hypothese, aber keine Angaben zu stützenden oder widersprechenden Befunden.','Definiere beobachtbare Kriterien und lege fest, wann du die Hypothese verwerfen oder einschränken würdest.',['hypothesis','evidencePlan'],true);
 const org=text(d,'outline');
 if(org&&!/diskussion|reflexion|grenz|kritisch/i.test(org))add('discussion','Aufbau und Zusammenhang','Diskussion in der Gliederung prüfen','In der Gliederung ist keine explizite Diskussion oder Reflexion erkennbar.','Plane einen Abschnitt für Interpretation, Gegenbefunde, Aussagegrenzen und Rückbezug auf die Frage.',['outline'],true);
 if(!tasks.length)add('schedule','Machbarkeit','Zeitplan noch nicht erstellt','Es sind keine geplanten Arbeitsphasen vorhanden.','Erstelle den Zeitplan und reserviere Zeit für Probelauf, Auswertung und Überarbeitung.',['start','deadline']);
 const paragraphs=['motivation','goal','procedure','analysis','claim','warrant','alternatives'];
 for(const k of paragraphs){const sentences=text(d,k).split(/(?<=[.!?])\s+/);const long=sentences.find(s=>s.split(/\s+/).length>38);if(long)add('long-'+k,'Präzision und Lesbarkeit','Langen Gedankenschritt aufteilen','Ein Satz umfasst mehr als 38 Wörter.','Trenne Behauptung, Begründung und Schlussfolgerung, ohne den Zusammenhang zu verlieren. Verknüpfungswörter allein belegen keine Logik.',[k],true)}
 const priority={"scope-method":0,causal:1,confirmation:2,testability:3,generalization:4,"missing-question":5,"missing-method":6};
 return findings.sort((a,b)=>(priority[a.id]??20)-(priority[b.id]??20));
}
const questions=[
 ['chain','Begründung und Schlussregel','Folgt die erwartete Schlussfolgerung tatsächlich aus den geplanten Belegen?','Suche eine verdeckte Voraussetzung. Könnten dieselben Daten auch eine andere Erklärung stützen?'],
 ['fit','Methode und Daten','Kann die Methode die Frage beantworten?','Prüfe Gegenstand, Stichprobe, Messgrössen oder Analysekategorien und Auswertung gemeinsam. Selbstauskünfte über Gründe sind kein automatischer Nachweis objektiver Ursachen.'],
 ['counter','Gegenargumente und Differenzierung','Was würde gegen deine Annahme sprechen?','Prüfe Gegenbeispiele und alternative Erklärungen ergebnisoffen. Ein Gegenargument muss nicht um jeden Preis entkräftet werden.'],
 ['sources','Belege und Quellen','Sind Belege zuverlässig und für genau diese Aussage relevant?','Prüfe Originalquelle, Kontext, Autorität und Aktualität. Erkläre bei Zitaten oder Paraphrasen den Bezug zur eigenen Untersuchung.'],
 ['coherence','Aufbau und Zusammenhang','Verwenden Frage, Teilfragen, Methode und Fazit dieselben Begriffe und denselben Geltungsbereich?','Eine Antwort auf eine andere Frage wäre trotz guter Einzelschritte inkonsistent. Prüfe auch die Zuordnung jeder Teilfrage.'],
 ['fallacies','Begründung und Schlussregel','Gibt es Zirkelschlüsse, falsche Alternativen oder vorschnelle Verallgemeinerungen?','Ein Beispiel belegt nicht alle Fälle; zeitliche Folge ist keine Kausalität; eine Autorität ersetzt keine Begründung. Prüfe die konkrete Schlussregel.']
];
root.KonzeptConsistency={analyze,questions};
})(typeof window==='undefined'?globalThis:window);
